('theory', 'kb_591', '{"tagId":"kb_591","originalNumber":591,"title":"評価の時間的不確実性","summary":"「何が幸で、何が不幸かは誰にもわからない」を支える概念。出来事の意味は後から変わりうるという作用や判断原理を説明する。","sourceType":"心理学","discipline":"ポジティブ心理学・人生設計","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["人生術","人生のつまずき"],"principles":["何が幸で、何が不幸かは誰にもわからない"],"relatedIds":[],"reliability":"出典・学術的位置づけ要確認","status":"seed","notes":"処世術Markdownで使用されていた未登録名称を統合時に追加。","categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 865),
